// Nyja e Thjeshte BST dhe Kerkimi
class Node:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

def search(root, key):
    if root is None or root.val == key: return root
    if root.val < key: return search(root.right, key)
    return search(root.left, key)
